-- Independent source aggregations; do not calculate expected values from exported events.
-- Blank filter cells mean all members. Dates are inclusive. Snapshot stays fixed.
\copy (WITH cases(case_id,start_date,end_date,branch_id,sku_id,outlet_id,channel) AS (VALUES ('all_2025',DATE '2025-01-01',DATE '2025-12-31',NULL::text,NULL::text,NULL::text,NULL::text),('all_2024',DATE '2024-01-01',DATE '2024-12-31',NULL,NULL,NULL,NULL),('all_history',DATE '2024-01-01',DATE '2025-12-31',NULL,NULL,NULL,NULL),('medan_2025',DATE '2025-01-01',DATE '2025-12-31','B003',NULL,NULL,NULL),('bandung_2025',DATE '2025-01-01',DATE '2025-12-31','B002',NULL,NULL,NULL),('jakarta_q1',DATE '2025-01-01',DATE '2025-03-31','B001',NULL,NULL,NULL),('partial_jan',DATE '2024-01-15',DATE '2024-01-31',NULL,NULL,NULL,NULL),('outlet_small',DATE '2025-01-01',DATE '2025-12-31',NULL,NULL,'O0170',NULL),('sku_first',DATE '2025-01-01',DATE '2025-12-31',NULL,(SELECT min(sku_id) FROM analytics.dim_product),NULL,NULL),('branch_sku',DATE '2025-04-01',DATE '2025-06-30','B003',(SELECT min(sku_id) FROM analytics.dim_product),NULL,NULL),('channel_first',DATE '2025-01-01',DATE '2025-12-31',NULL,NULL,NULL,(SELECT min(channel) FROM analytics.dim_outlet)),('empty_date',DATE '2024-01-01',DATE '2024-01-01','B003',(SELECT min(sku_id) FROM analytics.dim_product),'O0170',NULL)), result AS (SELECT c.*,s.gross_sales,s.discount_amount,s.billed_sales,r.return_amount,s.billed_sales-r.return_amount net_sales,s.billed_sales-r.return_amount-s.cogs_sold+r.returned_cogs gross_profit,s.reference_sales,s.price_shortfall,s.price_upside,s.invalid_promo_discount,s.orders,s.active_outlets,s.billed_sales/nullif(s.orders,0) average_order_value,(s.billed_sales-r.return_amount-s.cogs_sold+r.returned_cogs)/nullif(s.billed_sales-r.return_amount,0) gross_margin_rate,r.return_amount/nullif(s.billed_sales,0) return_rate FROM cases c CROSS JOIN LATERAL (SELECT coalesce(sum(gross_sales),0) gross_sales,coalesce(sum(discount_amount),0) discount_amount,coalesce(sum(net_sales_before_returns),0) billed_sales,coalesce(sum(cogs_sold),0) cogs_sold,coalesce(sum(quantity*reference_price),0) reference_sales,coalesce(sum(greatest(quantity*reference_price-gross_sales,0)),0) price_shortfall,coalesce(sum(greatest(gross_sales-quantity*reference_price,0)),0) price_upside,coalesce(sum(discount_amount) FILTER(WHERE promotion_id IS NOT NULL AND NOT is_promo_valid),0) invalid_promo_discount,count(DISTINCT sales_order_id) orders,count(DISTINCT outlet_id) active_outlets FROM analytics.fact_sales s WHERE sales_date BETWEEN c.start_date AND c.end_date AND (c.branch_id IS NULL OR s.branch_id=c.branch_id) AND (c.sku_id IS NULL OR s.sku_id=c.sku_id) AND (c.outlet_id IS NULL OR s.outlet_id=c.outlet_id) AND (c.channel IS NULL OR s.channel=c.channel)) s CROSS JOIN LATERAL (SELECT coalesce(sum(r.return_amount),0) return_amount,coalesce(sum(r.returned_cogs),0) returned_cogs FROM analytics.fact_returns r JOIN analytics.fact_sales sale USING(sales_line_id) WHERE return_date BETWEEN c.start_date AND c.end_date AND (c.branch_id IS NULL OR r.branch_id=c.branch_id) AND (c.sku_id IS NULL OR r.sku_id=c.sku_id) AND (c.outlet_id IS NULL OR r.outlet_id=c.outlet_id) AND (c.channel IS NULL OR sale.channel=c.channel)) r) SELECT result.* FROM result CROSS JOIN kpi_params p WHERE result.end_date<=p.as_of_date ORDER BY case_id) TO '/tmp/leakage-phase4/export/SQLFilterControls.csv' CSV HEADER ENCODING 'UTF8'
